1	import { chromium } from 'playwright';
2	import { mkdirSync } from 'node:fs';
3	import { log } from './logger.js';
4	
5	/**
6	 * 启动持久化浏览器上下文（复用登录态）。
7	 * 首次需有头人工登录一次，之后 session 保存在 userDataDir 中复用。
8	 */
9	export async function launchBrowser(cfg, { headless } = {}) {
10	  mkdirSync(cfg.userDataDir, { recursive: true });
11	  const launchOpts = {
12	    headless: headless ?? cfg.headless,
13	    viewport: { width: 1440, height: 900 },
14	    locale: 'zh-CN',
15	    timezoneId: 'Asia/Shanghai',
16	    args: ['--disable-blink-features=AutomationControlled'],
17	  };
18	  // 走代理（Clash/Mihomo 等），否则直连海外网关会被频繁重置
19	  if (cfg.proxy) {
20	    launchOpts.proxy = { server: cfg.proxy };
21	    log.info(`使用代理：${cfg.proxy}`);
22	  }
23	  const context = await chromium.launchPersistentContext(cfg.userDataDir, launchOpts);
24	  context.setDefaultNavigationTimeout(cfg.navTimeoutMs);
25	  context.setDefaultTimeout(15000);
26	  const page = context.pages()[0] || await context.newPage();
27	  return { context, page };
28	}
29	
30	/**
31	 * 带重试+退避的导航。Temu 网关（Azure Traffic Manager → gw-sg）会偶发重置连接
32	 * （ERR_CONNECTION_CLOSED / ERR_NETWORK_CHANGED 等），前 1-2 次常被重置，重试几次
33	 * 连接「热」起来后即稳定 200。诊断（netdiag.mjs）已证实：
34	 *  - waitUntil:'commit' 重试 2-3 次即可穿过间歇性重置；
35	 *  - waitUntil:'domcontentloaded' 因商品列表是重型 SPA、网络长期不空闲，事件永不触发 → 必超时。
