// 最小验证：修检测后，真实 Chrome + 复用登录态能否让商品列表页正常出数据。
// 只读顶部 tab 数字 + 数商品行 + 截图，不碰 stores.js 的待重写选择器。
import { loadConfig } from './src/config.js';
import { launchBrowser, gotoWithRetry, waitForGoodsList } from './src/browser.js';
import { log } from './src/logger.js';

const OUT = 'C:\\Users\\Administrator\\AppData\\Local\\Temp\\claude\\E--project-temu\\39c2c9b3-8b05-4fa9-a38d-ee426277b3c7\\scratchpad\\verify-detect.png';

const cfg = loadConfig();
log.info('channel=', cfg.channel, ' userDataDir=', cfg.userDataDir);

const { context, page } = await launchBrowser(cfg, { headless: false });
try {
  const navOk = await gotoWithRetry(page, cfg.goodsListUrl, cfg);
  log.info('navOk=', navOk, ' url=', page.url());

  const gridOk = await waitForGoodsList(page, { timeout: cfg.navTimeoutMs });
  log.info('waitForGoodsList=', gridOk);
  await page.waitForTimeout(6000); // 给网格数据接口时间

  // 读顶部状态 tab 文本
  const tabs = await page.getByText(/全部\s*\d+|在售中\s*\d+/).allInnerTexts().catch(() => []);
  log.info('TABS:', JSON.stringify(tabs));

  const onSale = (('' + tabs).match(/在售中\s*(\d+)/) || [])[1] ?? null;
  log.info('在售中 =', onSale);

  // 数商品行：SKC ID 出现次数 ≈ 商品数（网格真正渲染出来才有）
  const skcCount = await page.getByText(/SKC\s*ID/i).count().catch(() => 0);
  // 是否还卡在「加载中」
  const loading = await page.getByText(/加载中/).first().isVisible().catch(() => false);
  log.info('渲染出的商品行(SKC ID 数) =', skcCount, ' 页面仍显示「加载中」=', loading);

  await page.screenshot({ path: OUT, fullPage: false }).catch((e) => log.warn('截图失败', e.message));
  log.info('截图已存:', OUT);

  log.info(skcCount > 0 && !loading
    ? '✅ 结论：修检测成功，商品网格正常出数据！'
    : '❌ 结论：网格仍未出数据（可能还需选地区/店铺，或风控仍拦截）。');
} finally {
  await page.waitForTimeout(1500);
  await context.close().catch(() => {});
}

