14	export async function calibrate(cfg) {
15	  // headless 下网关重置期更稳（有头模式重置阵发期易 frame detached 崩溃）；
16	  // 截图/响应体捕获在无头下同样有效。可用 CALIB_HEADED=1 强制有头做人工观察。
17	  const headed = process.env.CALIB_HEADED === '1';
18	  const { context, page } = await launchBrowser(cfg, { headless: !headed });
19	  const apiUrls = new Set();
20	  page.on('request', (req) => {
21	    const t = req.resourceType();
22	    if (t === 'xhr' || t === 'fetch') apiUrls.add(`${req.method()} ${req.url()}`);
23	  });
24	
25	  // 关键新增：把疑似商品数据接口的 JSON 响应体落盘，供离线反推字段名
26	  const bodiesDir = resolve(ROOT, 'data', 'calibrate-bodies');
27	  mkdirSync(bodiesDir, { recursive: true });
28	  const bodyIndex = [];
29	  let bodySeq = 0;
30	  page.on('response', async (resp) => {
31	    try {
32	      const url = resp.url();
33	      const ct = resp.headers()['content-type'] || '';
34	      if (!ct.includes('json')) return;
35	      // 抓「全部」业务 JSON（不再按 URL 关键词预筛，免得漏掉列表接口），仅跳过明显噪声
36	      if (/menu|\/auth\/|feedback|_stm|pmm|robin|exam|redDot|leo-config|report\/uin|env\?|jump\/token/i.test(url)) return;
37	      const text = await resp.text();
38	      if (!text || text.length < 40) return; // 太短多半是计数/开关类，跳过
39	      const seq = String(++bodySeq).padStart(2, '0');
40	      const file = `body-${seq}.json`;
41	      const hit = /在售|流量|onSale|skcId|goodsList|productList|traffic/i.test(text);
42	      writeFileSync(
43	        resolve(bodiesDir, file),
44	        `// ${resp.request().method()} ${url}\n// status=${resp.status()} hitKeywords=${hit}\n${text}`,
45	        'utf8'
46	      );
47	      bodyIndex.push(`${file}  hit=${hit}  ${resp.request().method()} ${url}`);
48	    } catch { /* ignore */ }
49	  });
50	
51	  if (!(await isLoggedIn(page, cfg))) {
52	    log.error('未登录，请先 npm run login');
53	    await context.close();
54	    return;
55	  }
56	  await closePopups(page);
57	  log.info('已进入商品列表页，采集接口与 DOM 中…（约 25 秒）');
58	  await page.waitForTimeout(5000);
59	
60	  // 页面外壳常只渲染菜单，需显式点「商品列表」菜单项进入真正的表格视图
61	  const menu = page.getByText(/^商品列表$/).first();
62	  if (await menu.isVisible({ timeout: 2000 }).catch(() => false)) {
63	    await menu.click({ timeout: 3000 }).catch(() => {});
64	    log.info('已点击「商品列表」菜单项，等待表格渲染…');
65	    await page.waitForTimeout(6000);
66	  }
67	  await closePopups(page);
68	
69	  // 点一下「在售中」标签，触发列表接口
70	  const tab = page.getByText(/在售中\s*\d*/).first();
71	  if (await tab.isVisible({ timeout: 2000 }).catch(() => false)) {
72	    await tab.click({ timeout: 3000 }).catch(() => {});
73	    log.info('已点击「在售中」标签。');
74	  } else {
75	    log.warn('未见「在售中」标签，可能表格仍未渲染。');
76	  }
77	  await page.waitForTimeout(3000);
78	  // 关键：网格「加载中」多因通知面板遮挡/抢焦点，先再清一轮弹窗
79	  await closePopups(page);
80	  // 落盘当前整页 HTML（面板仍在时），便于离线核对通知面板 X 的真实选择器
81	  writeFileSync(resolve(ROOT, 'data', 'calib-after-close.html'), await page.content().catch(() => ''), 'utf8');
82	  // 等网格数据真正出现（在售中 / 商品行）
83	  await page.getByText(/在售中\s*\d+/).first().waitFor({ state: 'visible', timeout: 20000 }).catch(() => {});
84	  await page.waitForTimeout(2000);
85	  await page.screenshot({ path: resolve(ROOT, 'data', 'calib-shot-01-list.png') }).catch(() => {});
86	  // 轻微滚动，触发懒加载/分页接口
87	  await page.mouse.wheel(0, 1200).catch(() => {});
88	  await page.waitForTimeout(3000);
89	  await page.screenshot({ path: resolve(ROOT, 'data', 'calib-shot-02-scrolled.png'), fullPage: true }).catch(() => {});
90	
91	  // 保存接口清单
92	  const apiList = [...apiUrls].filter((u) => /goods|product|list|query|mms|mall|shop|search/i.test(u));
93	  writeFileSync(
94	    resolve(ROOT, 'data', 'calibrate-apis.txt'),
95	    [...apiUrls].sort().join('\n'),
96	    'utf8'
97	  );
98	  log.info(`接口清单已保存（${apiUrls.size} 条），疑似相关：`);
99	  for (const u of apiList.slice(0, 40)) log.info('  ', u);
100	
101	  // 保存响应体索引
102	  writeFileSync(
103	    resolve(ROOT, 'data', 'calibrate-bodies', '_index.txt'),
104	    bodyIndex.join('\n') || '(未捕获到任何疑似商品接口响应体)',
105	    'utf8'
106	  );
107	  log.info(`已落盘 ${bodyIndex.length} 个疑似商品接口响应体到 data/calibrate-bodies/`);
108	  for (const b of bodyIndex.filter((x) => /hit=true/.test(x))) log.info('  ★', b);
109	
110	  // 保存顶部 header HTML（含店铺切换器）
111	  const headerHtml = await page
112	    .locator('header, [class*="header" i], [class*="Header" i]')
113	    .first()
114	    .innerHTML()
115	    .catch(() => '');
116	  writeFileSync(resolve(ROOT, 'data', 'calibrate-header.html'), headerHtml, 'utf8');
117	
118	  // 保存整页可见文本片段（辅助核对标签/芯片文案）
119	  const bodyText = await page.locator('body').innerText().catch(() => '');
120	  writeFileSync(resolve(ROOT, 'data', 'calibrate-bodytext.txt'), bodyText, 'utf8');
121	
122	  // 保存「切换前」整页 HTML，供离线核对
123	  writeFileSync(
124	    resolve(ROOT, 'data', 'calibrate-page-before.html'),
125	    await page.content().catch(() => ''),
126	    'utf8'
127	  );
128	
129	  // 自动尝试打开店铺切换器：逐个试候选触发区，打开后把整页 HTML 存盘，
130	  // 供离线分析下拉结构（stores.js 的 SWITCHER_TRIGGERS / STORE_ITEM_SELECTORS 据此微调）。
131	  const SWITCHER_CANDIDATES = [
132	    '[class*="MallSelect"]',
133	    '[class*="mall-select"]',
134	    '[class*="shopSelect"]',
135	    '[class*="StoreSelect"]',
136	    '[class*="mallName" i]',
137	    '[class*="shopName" i]',
138	    'header [class*="select" i]',
139	  ];
140	  let openedBy = '';
141	  for (const sel of SWITCHER_CANDIDATES) {
142	    const el = page.locator(sel).first();
143	    if (await el.isVisible({ timeout: 400 }).catch(() => false)) {
144	      await el.click({ timeout: 1500 }).catch(() => {});
145	      await page.waitForTimeout(1200);
146	      openedBy = sel;
147	      break;
148	    }
149	  }
150	  writeFileSync(
151	    resolve(ROOT, 'data', 'calibrate-page-switcher-open.html'),
152	    await page.content().catch(() => ''),
153	    'utf8'
154	  );
155	  writeFileSync(
