158	    'utf8'
159	  );
160	  if (openedBy) log.info(`已自动点开疑似店铺切换器（命中 ${openedBy}），整页 HTML 已存盘。`);
161	  else log.warn('未自动命中店铺切换器候选，请在接下来 20 秒内手动点开，我已存下切换前整页 HTML 供比对。');
162	
163	  log.info('校准文件已写入 data/：calibrate-apis.txt / calibrate-header.html / calibrate-bodytext.txt / calibrate-page-before.html / calibrate-page-switcher-open.html / calibrate-switcher-meta.txt');
